<?php
defined('ROOT') || exit;
/* print the top of the HTML page (head tag, styles, fonts) */
function page_head($t)
{
    global $me;
    echo '<!doctype html><html lang=en data-theme="' . esc($me['a_theme'] ?? 'light') . '"' . ($me ? ' data-user' : '') . (!empty($me['a_calm']) ? ' data-calm' : '') . '><head><meta charset=utf-8><script>(function(){var h=document.documentElement,t=h.getAttribute("data-theme");try{if(h.hasAttribute("data-user"))localStorage.setItem("unsent-theme",t);else t=localStorage.getItem("unsent-theme")||t}catch(e){}h.setAttribute("data-theme",t);if(t=="auto")t=matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light";h.setAttribute("data-eff",t||"light");try{if(!sessionStorage.getItem("fx-seen")){h.classList.add("fx-first");sessionStorage.setItem("fx-seen",1)}}catch(e){}})();addEventListener("pagereveal",function(e){if(e.viewTransition&&document.documentElement.hasAttribute("data-calm"))e.viewTransition.skipTransition()})</script><meta name=viewport content="width=device-width,initial-scale=1"><meta name=csrf content="' . esc($GLOBALS['CSRF']) . '"><link rel=preconnect href="https://fonts.googleapis.com"><link rel=preconnect href="https://fonts.gstatic.com" crossorigin><title>' . $t . ' · Unsent</title><link href="https://fonts.googleapis.com/css2?family=Caveat:wght@500;700&family=Dancing+Script:wght@500;700&family=Kalam:wght@400;700&family=Lora:wght@500;700&family=Special+Elite&family=Manrope:wght@400;500;600;700&display=swap" rel=stylesheet><link rel=stylesheet href="css/style.css?v=' . filemtime(ROOT . '/css/style.css') . '"><link rel=stylesheet href="css/motion.css?v=' . @filemtime(ROOT . '/css/motion.css') . '"><link rel=stylesheet href="css/responsive.css?v=' . @filemtime(ROOT . '/css/responsive.css') . '"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></head><body' . (!empty($me['a_calm']) ? ' class=calm' : '') . '><a class=skip href="#main">Skip to content</a>';
}
